import * as THREE from './assets/three.module.js';
import {DRACOLoader} from './assets/DRACOLoader.js';
import {GLTFLoader} from './assets/GLTFLoader.js';
export const missionData=[
 {id:'hubble',name:'Hubble',parent:'earth',width:.0132,alt:550,credit:'NASA / DigitalSpace Corporation',source:'https://science.nasa.gov/3d-resources/hubble-space-telescope-a/',description:'Telescopio espacial lanzado en 1990. Su espejo de 2,4 metros transformó nuestra visión del universo. Modelo oficial de NASA; ubicación orbital recreada.'},
 {id:'juno',name:'Juno',parent:'jupiter',width:.020,alt:5000,credit:'NASA',source:'https://science.nasa.gov/3d-resources/juno-b/',description:'Los tres grandes paneles solares de Juno alimentan su exploración de Júpiter desde 2016. Esta escena recrea una visita a Júpiter; no representa su posición actual.'},
 {id:'voyager',name:'Voyager',parent:'jupiter',width:.020,alt:100000,credit:'NASA / Christopher R. Meaney',source:'https://science.nasa.gov/3d-resources/voyager-probe-a/',description:'Una antena de 3,7 metros y una larga pértiga de instrumentos: las sondas Voyager visitaron Júpiter en 1979. Aquí se recrea aquel encuentro. Hoy ambas están mucho más allá de Plutón.'},
 {id:'new-horizons',name:'New Horizons',parent:'pluto',width:.003,alt:12500,credit:'NASA VTAD',source:'https://science.nasa.gov/resource/new-horizons-3d-model/',description:'New Horizons reveló Plutón y Caronte en julio de 2015. Esta recreación mantiene la sonda cerca de Plutón para explorar su modelo; su posición actual es exterior al sistema representado.'}
];
const draco=new DRACOLoader().setDecoderPath('assets/').setDecoderConfig({type:'wasm'});const loader=new GLTFLoader().setDRACOLoader(draco),models=new Map();
export async function missionModel(id){if(!models.has(id))models.set(id,loader.loadAsync('assets/missions/'+id+'.glb').then(g=>{const model=g.scene;model.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),root=new THREE.Group();root.add(model);model.position.sub(center);root.scale.setScalar(2/Math.max(size.x,size.y,size.z));root.updateMatrixWorld(true);return root;}));return models.get(id);}
// Painter renderer for the inspection view on machines without WebGL. Geometry
// comes from the same NASA GLB, with subpixel faces omitted during painting.
export function modelTriangles(model){const triangles=[];model.updateMatrixWorld(true);model.traverse(mesh=>{if(!mesh.isMesh)return;const p=mesh.geometry.attributes.position,idx=mesh.geometry.index,uv=mesh.geometry.attributes.uv,vertexColor=mesh.geometry.attributes.color,mat=Array.isArray(mesh.material)?mesh.material[0]:mesh.material,color=mat.color?.clone()||new THREE.Color(.7,.7,.7),vertices=[];for(let i=0;i<p.count;i++){const v=new THREE.Vector3().fromBufferAttribute(p,i).applyMatrix4(mesh.matrixWorld);vertices.push(v);}let map=null;if(mat.map?.image){try{const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');ctx.drawImage(mat.map.image,0,0,128,128);map=ctx.getImageData(0,0,128,128).data;}catch{}}
 const count=idx?idx.count:p.count;for(let i=0;i<count;i+=3){const ids=[0,1,2].map(j=>idx?idx.getX(i+j):i+j),v=ids.map(j=>vertices[j]);if(v.some(x=>!x))continue;const a=v[1].clone().sub(v[0]),b=v[2].clone().sub(v[0]),n=a.cross(b);if(n.lengthSq()<1e-13)continue;const rgb=color.clone();if(vertexColor){const c=new THREE.Color();c.setRGB(ids.reduce((sum,j)=>sum+vertexColor.getX(j),0)/3,ids.reduce((sum,j)=>sum+vertexColor.getY(j),0)/3,ids.reduce((sum,j)=>sum+vertexColor.getZ(j),0)/3);rgb.multiply(c);}if(map&&uv){const u=ids.reduce((sum,j)=>sum+uv.getX(j),0)/3,t=ids.reduce((sum,j)=>sum+uv.getY(j),0)/3,k=(Math.min(127,Math.max(0,Math.floor(t*128)))*128+((Math.floor(u*128)%128+128)%128))*4;rgb.setRGB(map[k]/255,map[k+1]/255,map[k+2]/255,THREE.SRGBColorSpace);}triangles.push({v,n:n.normalize(),color:rgb});}});return triangles;}
export function paintModel(ctx,triangles,quaternion,width,height,zoom=1,screenCenter=null,sunDirection=null){const scale=Math.min(width,height)*.31*zoom,center=screenCenter||[width/2,height/2],light=sunDirection||new THREE.Vector3(-.4,.7,1).normalize(),result=[];for(const t of triangles){const v=t.v.map(p=>p.clone().applyQuaternion(quaternion)),n=t.n.clone().applyQuaternion(quaternion),depth=(v[0].z+v[1].z+v[2].z)/3;const shade=.09+.91*Math.max(0,n.dot(light)),c=t.color.clone().multiplyScalar(shade);result.push({v,depth,c});}result.sort((a,b)=>a.depth-b.depth);for(const t of result){const screen=t.v.map(p=>[center[0]+p.x*scale,center[1]-p.y*scale]);const area=Math.abs((screen[1][0]-screen[0][0])*(screen[2][1]-screen[0][1])-(screen[1][1]-screen[0][1])*(screen[2][0]-screen[0][0]));if(area<.1)continue;ctx.fillStyle='#'+t.c.getHexString();ctx.beginPath();ctx.moveTo(...screen[0]);ctx.lineTo(...screen[1]);ctx.lineTo(...screen[2]);ctx.closePath();ctx.fill();}}
export class MissionGallery{
 constructor(dialog,software){this.dialog=dialog;this.canvas=document.getElementById('missionCanvas');this.software=software;this.quaternion=new THREE.Quaternion().setFromEuler(new THREE.Euler(.85,-.6,.2));this.zoom=1.35;this.selected='juno';this.scene=new THREE.Scene();this.camera=new THREE.PerspectiveCamera(40,2,.01,100);this.camera.position.z=4;this.scene.add(new THREE.HemisphereLight(0xdbeaff,0x343c48,2));const light=new THREE.DirectionalLight(0xfff1dc,3);light.position.set(-3,4,5);this.scene.add(light);if(!software){this.renderer=new THREE.WebGLRenderer({canvas:this.canvas,alpha:true,antialias:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));}else this.ctx=this.canvas.getContext('2d');
 for(const m of missionData){const b=document.createElement('button');b.textContent=m.name;b.dataset.mission=m.id;b.onclick=()=>this.select(m.id);document.getElementById('missionTabs').append(b);}document.getElementById('closeMissions').onclick=()=>dialog.close();let last=null;this.canvas.onpointerdown=e=>{last=[e.clientX,e.clientY];this.canvas.setPointerCapture(e.pointerId);};this.canvas.onpointerup=()=>last=null;this.canvas.onpointercancel=()=>last=null;this.canvas.onpointermove=e=>{if(!last)return;const q=new THREE.Quaternion().setFromEuler(new THREE.Euler((e.clientY-last[1])*.008,(e.clientX-last[0])*.008,0));this.quaternion.premultiply(q);last=[e.clientX,e.clientY];this.draw();};this.canvas.onwheel=e=>{e.preventDefault();this.zoom=THREE.MathUtils.clamp(this.zoom*Math.exp(-e.deltaY*.001),.4,3);this.draw();};this.canvas.addEventListener('wheel',()=>{},{passive:false});window.addEventListener('resize',()=>{if(dialog.open)this.draw();});}
 open(){this.dialog.showModal();this.select(this.selected);}
 async select(id){this.selected=id;const m=missionData.find(x=>x.id===id);document.querySelectorAll('[data-mission]').forEach(b=>b.classList.toggle('active',b.dataset.mission===id));document.getElementById('missionName').textContent=m.name;document.getElementById('missionDescription').textContent=m.description;document.getElementById('missionCredits').innerHTML=`Modelo: ${m.credit} · <a href="${m.source}" target="_blank" rel="noreferrer">Fuente oficial</a> · Dimensión máxima de la recreación: ${m.width*1000} m. Las ubicaciones son escenas históricas aproximadas, no efemérides de las sondas.`;document.getElementById('missionLoading').textContent='Cargando modelo tridimensional…';try{const model=await missionModel(id);if(this.selected!==id)return;if(this.model)this.scene.remove(this.model);this.model=model.clone(true);this.scene.add(this.model);this.triangles=this.software?modelTriangles(model):null;document.getElementById('missionLoading').textContent='Modelo listo';this.draw();}catch(e){document.getElementById('missionLoading').textContent='No se pudo cargar el modelo. Vuelve a seleccionarlo.';console.error(e);}}
 draw(){if(!this.model)return;const w=this.canvas.clientWidth,h=this.canvas.clientHeight;if(this.renderer){this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.position.z=4/this.zoom;this.camera.updateProjectionMatrix();this.model.quaternion.copy(this.quaternion);this.renderer.render(this.scene,this.camera);}else{this.canvas.width=w* Math.min(devicePixelRatio,1.5);this.canvas.height=h*Math.min(devicePixelRatio,1.5);this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height);paintModel(this.ctx,this.triangles,this.quaternion,this.canvas.width,this.canvas.height,this.zoom);}}
}
